-- GenDB engine variant Q07-conjunct_permutation: template q07.sql, kind conjunct_permutation (generated by generate.py; frozen)
SELECT
  supp_nation,
  cust_nation,
  l_year,
  SUM(volume) AS revenue
FROM (
  SELECT
    n1.n_name AS supp_nation,
    n2.n_name AS cust_nation,
    EXTRACT(YEAR FROM l_shipdate) AS l_year,
    l_extendedprice * (
      1 - l_discount
    ) AS volume
  FROM supplier, lineitem, orders, customer, nation AS n1, nation AS n2
  WHERE
    l_shipdate BETWEEN CAST('1995-01-01' AS DATE) AND CAST('1996-12-31' AS DATE)
    AND (
      (
        n2.n_name = $2 AND n1.n_name = $1
      )
      OR (
        n2.n_name = $1 AND n1.n_name = $2
      )
    )
    AND c_nationkey = n2.n_nationkey
    AND s_nationkey = n1.n_nationkey
    AND c_custkey = o_custkey
    AND o_orderkey = l_orderkey
    AND s_suppkey = l_suppkey
) AS shipping
GROUP BY
  supp_nation,
  cust_nation,
  l_year
ORDER BY
  supp_nation,
  cust_nation,
  l_year
